package com.stan.lightphotobackup.database
import androidx.room.*
@Entity(tableName="backup_records",indices=[Index(value=["mediaStoreVolume","mediaStoreId"],unique=true),Index("status"),Index("dateTakenMillis"),Index("contentFingerprint")])
data class BackupRecord(@PrimaryKey(autoGenerate=true) val id:Long=0,val mediaStoreId:Long,val mediaStoreVolume:String,val contentUri:String,val displayName:String?,val relativePath:String?,val mimeType:String,val sizeBytes:Long,val dateTakenMillis:Long?,val dateAddedSeconds:Long?,val dateModifiedSeconds:Long?,val width:Int?,val height:Int?,val contentFingerprint:String?=null,val status:BackupStatus=BackupStatus.DISCOVERED,val attemptCount:Int=0,val lastAttemptMillis:Long?=null,val nextRetryMillis:Long?=null,val uploadedAtMillis:Long?=null,val googleMediaItemId:String?=null,val uploadToken:String?=null,val uploadTokenCreatedAtMillis:Long?=null,val lastErrorCode:String?=null,val lastErrorMessage:String?=null,val createdAtMillis:Long,val updatedAtMillis:Long)
@Entity(tableName="backup_summary") data class BackupSummary(@PrimaryKey val id:Int=1,val lastScanMillis:Long?=null,val lastAttemptMillis:Long?=null,val lastSuccessMillis:Long?=null,val discovered:Int=0,val uploaded:Int=0,val waiting:Int=0,val failed:Int=0,val currentPosition:Int=0,val operation:String="Idle",val lastError:String?=null,val pathCategories:String="")
